function validate(input,rows){const p=copy(input);need(p&&p.v===1&&p.scene&&p.scene.w===12&&p.scene.h===10,'ข้อมูลสนามทดสอบไม่ถูกต้อง');p.scene=D.validate({v:1,scenes:[p.scene]}).scenes[0];need(N.classes[p.job]&&N.weapons[p.weapon]&&N.classes[p.job].weapons.includes(N.weapons[p.weapon].type),'อาวุธไม่ตรงคลาสจำลอง');need(Number.isInteger(p.seed)&&p.seed>=0&&p.seed<=4294967295&&Number.isInteger(p.aim)&&p.scene.cells[p.aim],'รหัสสุ่มหรือช่องเป้าหมายผิด');need(Number.isInteger(p.hero)&&p.scene.cells[p.hero]&&D.walkable(p.scene.cells[p.hero]),'ช่องผู้ทดสอบต้องเดินได้');need(Array.isArray(p.monsters)&&p.monsters.length<=5,'วางมอนสเตอร์ได้สูงสุด 5 ตัว');const occupied=new Set([p.hero]);for(const m of p.monsters){need(Number.isInteger(m.cell)&&p.scene.cells[m.cell]&&D.walkable(p.scene.cells[m.cell])&&!occupied.has(m.cell),'มอนสเตอร์ต้องอยู่ช่องว่างที่เดินได้');need(rows.some(r=>r.kind==='monster'&&r.id===m.id&&r.enabled!==false),'ไม่พบมอนสเตอร์ที่เปิดใช้');occupied.add(m.cell);}if(p.displacementTest)F.validate(p.displacementTest);if(p.enemyDisplacement!==undefined)need(typeof p.enemyDisplacement==='boolean','สถานการณ์มอนสเตอร์ผลักไม่ถูกต้อง');if(p.statusTest)need(['poison','burn','frozen','stun','resist','immune','enemy','cure'].includes(p.statusTest),'สถานการณ์สถานะผิด');if(p.patternTest)G.validate(p.patternTest);if(p.senses)need(Number.isInteger(p.senses.sight)&&p.senses.sight>=1&&p.senses.sight<=20&&Number.isInteger(p.senses.hearing)&&p.senses.hearing>=1&&p.senses.hearing<=10,'ระยะมอง 1–20 / ได้ยิน 1–10');return p;}
function build(input,rows){const plan=validate(input,rows);need(plan.monsters.length,'วางมอนสเตอร์อย่างน้อย 1 ตัว');const sim=R.fresh();R.createCharacter(sim,'ผู้ทดสอบจำลอง','human',plan.job,{},N.recommend({...N.draft(),job:plan.job,weapon:plan.weapon}));sim.character.level=10;sim.character.skills=Object.keys(N.skills);sim.character.inventory.reagents=99;sim.hp=N.maxHp(sim.character);sim.mp=sim.maxMp=5000;sim.learned=rows.filter(r=>A.compile(r)).map(r=>r.key);const units=[];let e;
for(const [i,m]of plan.monsters.entries()){const bootstrap=copy(plan.scene);for(const c of bootstrap.cells){c.spawn='';c.monster='';c.object='none';c.height=0;}bootstrap.cells[plan.hero].spawn='player';bootstrap.cells[m.cell].spawn='enemy';bootstrap.cells[m.cell].monster=m.id;const part=C.create(bootstrap,sim,rows.filter(r=>r.kind==='monster'),'lab-'+plan.seed,()=>0,{tactical:true,enemyCount:1});if(!e)e=part;const u=part.units[1];u.id='enemy-'+i;u.n=D.node(m.cell);u.detected=['hero'];u.aware=['hero'];units.push(u);}
e.scene=copy(plan.scene);for(const c of e.scene.cells){c.spawn='';c.monster='';}e.scene.cells[plan.hero].spawn='player';for(const m of plan.monsters){e.scene.cells[m.cell].spawn='enemy';e.scene.cells[m.cell].monster=m.id;}e.units=[e.units[0],...units];e.units[0].n=D.node(plan.hero);e.units[0].detected=units.map(u=>u.id);e.potions=99;e.seed=plan.seed||1;e.detectSeed=plan.seed||1;e.detectChecks={};e.log=['สนามจำลอง • ไม่มีรางวัลและไม่บันทึกความก้าวหน้า'];S.initialize(e,rows);M.prepare(e,rows);P.prepare(e,rows);A.prepare(e,sim,rows);G.prepare(e,rows);Z.prepare(e,rows);F.prepare(e,rows);if(plan.displacementTest){const hero=e.units[0];hero.hp=hero.maxHp=hero.baseMaxHp=200;for(const u of e.units.slice(1))u.hp=u.maxHp=200;if(plan.enemyDisplacement){const u=e.units[1],a=u.monsterCombat.actions.find(a=>a.magic)||u.monsterCombat.actions[0];need(a,'มอนสเตอร์ไม่มีสกิลที่รองรับ');a.displacement=copy(plan.displacementTest);a.statusConfig={kinds:[],chance:100,turns:2,damage:3,dc:0,stat:'CON'};u.monsterCombat.actions=[a];}else{const a=e.catalogActions.find(a=>a.id===plan.action);a.displacement=copy(plan.displacementTest);a.statusConfig={kinds:[],chance:100,turns:2,damage:3,dc:0,stat:'CON'};}}if(plan.statusTest){const k=plan.statusTest,u=e.units[1],hero=e.units[0],config={kinds:[['immune','resist','enemy','cure'].includes(k)?'poison':k],chance:100,turns:2,damage:5,dc:k==='resist'?1:0,stat:'CON'};u.hp=u.maxHp=Math.max(u.maxHp,200);hero.hp=hero.maxHp=hero.baseMaxHp=200;if(k==='enemy'){const a=u.monsterCombat.actions.find(a=>a.magic)||u.monsterCombat.actions[0];need(a,'มอนสเตอร์ไม่มีสกิลที่รองรับ');a.statusConfig=config;a.roll={n:1,sides:2,bonus:0};u.monsterCombat.actions=[a];u.cooldowns={};}else if(k==='cure'){Z.apply(e,hero,'poison',2,5);Z.apply(e,hero,'frozen',1);Z.clear(hero,'frozen');Z.apply(e,u,'stun',2);}else{const a=e.catalogActions.find(a=>a.id===plan.action);a.statusConfig=config;}}if(plan.senses){e.units[0].sightRange=plan.senses.sight;e.units[0].hearingRange=plan.senses.hearing;}e.gridDirection=plan.direction??-1;if(plan.patternTest){const action=e.catalogActions.find(a=>a.id===(plan.patternAbility||plan.action));need(action,'ไม่พบสกิลสำหรับทดสอบรูปพื้นที่');action.grid=copy(plan.patternTest);}C.validate(e);return {v:1,plan,e,last:null};}
function footprint(scene,cell){const x=cell%scene.w,y=Math.floor(cell/scene.w),out=[];for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(x+dx>=0&&x+dx<scene.w&&y+dy>=0&&y+dy<scene.h)out.push((y+dy)*scene.w+x+dx);return out;}
function ability(session,id){if(id==='lab:area3')return {name:'แม่แบบทดสอบพื้นที่ 3×3',description:'ท่าจำลองสำหรับดูพื้นที่ • ไฟ 30 • 8 MP / 1 AP • เล็งกลางระยะ 4 • ไม่พลาด • ไม่ใช่สกิลที่ปลดล็อกในเกมจริง'};if(id==='basic')return {name:'โจมตีปกติ',description:'ใช้ระยะ อาวุธ และโอกาสโดนตามระบบต่อสู้จริง'};const a=A.list(session.e).find(a=>a.id===id)||N.skills[id];return a?{...a,...(session.e.gridSkills?.[id]?{grid:session.e.gridSkills[id]}:{}),displacement:a.displacement||F.config(session.e,id),...(session.e.statusSkills?.[id]?{statusConfig:session.e.statusSkills[id]}:{})}:a;}
function act(session,id,cell,ids){const e=session.e,before=copy(e);need(Number.isInteger(cell)&&e.scene.cells[cell],'เลือกช่องในสนาม');try{const p=C.hero(e),a=ability(session,id);need(a,'รายการนี้ยังไม่รองรับ');const hp=new Map(e.units.map(u=>[u.id,u.hp])),statuses=new Map(e.units.map(u=>[u.id,Z.describe(u)])),positions=new Map(e.units.map(u=>[u.id,D.index(u.n)]));if(id==='lab:area3'){need(e.status==='active'&&p.hp>0&&p.action>0&&!p.casting&&!Z.blocked(p)&&!p.effects.silence&&p.mana>=8,'ต้องมี 1 AP / 8 MP และไม่ติดสถานะขัดขวาง');const center={n:D.node(cell),hp:1,side:'enemy'};need(C.tactical.canTarget(e,p,center,{min:0,max:4,mode:'single',count:1,side:'enemy',heights:[-2,-1,0,1,2]}),'จุดกลางอยู่นอกระยะ ความสูง หรือมีกำแพงบัง');const area=new Set(footprint(e.scene,cell)),rule={min:0,max:6,mode:'all',count:13,side:'enemy',heights:[-2,-1,0,1,2]},previous=e.currentTargeting;p.action--;p.mana-=8;e.currentTargeting=rule;try{for(const u of e.units.filter(u=>u.side==='enemy'&&u.hp>0&&area.has(D.index(u.n))))X.damage(e,p,u,1,{base:30,magic:true,element:'Fire',sure:true,area:true});}finally{if(previous===undefined)delete e.currentTargeting;else e.currentTargeting=previous;}e.log.unshift('ทดสอบพื้นที่ 3×3 • กลาง '+(cell%e.scene.w+1)+','+(Math.floor(cell/e.scene.w)+1));e.log=e.log.slice(0,30);}
else{const target=e.units.find(u=>u.hp>0&&u.side==='enemy'&&D.index(u.n)===cell);if(id==='basic'){need(target,'เลือกช่องมอนสเตอร์');C.attack(e,target.id);}else{const ally=a.targeting?.side==='ally';C.cast(e,id,ids||(ally?'hero':target?.id),cell);}}
C.validate(e);session.last={name:a.name,cell,changes:e.units.map(u=>({id:u.id,name:u.name,side:u.side,cell:D.index(u.n),beforeCell:positions.get(u.id),before:hp.get(u.id),after:u.hp,delta:hp.get(u.id)-u.hp,statusBefore:statuses.get(u.id)||'',statusAfter:Z.describe(u)}))};return session.last;
}catch(err){session.e=before;throw err;}}
function endTurn(session){const before=copy(session.e),hp=new Map(session.e.units.map(u=>[u.id,u.hp])),statuses=new Map(session.e.units.map(u=>[u.id,Z.describe(u)])),positions=new Map(session.e.units.map(u=>[u.id,D.index(u.n)]));try{C.endTurn(session.e);C.validate(session.e);session.last={name:'เทิร์นมอนสเตอร์',cell:null,changes:session.e.units.map(u=>({id:u.id,name:u.name,side:u.side,cell:D.index(u.n),beforeCell:positions.get(u.id),before:hp.get(u.id),after:u.hp,delta:hp.get(u.id)-u.hp,statusBefore:statuses.get(u.id)||'',statusAfter:Z.describe(u)}))};return session.last;}catch(error){session.e=before;throw error;}}
